$views=['overview','cohorts','students','tests','lessons','pages'];
$view=(string)($_GET['view']??'overview');
if(!in_array($view,$views,true))$view='overview';

function student_admin_url(int $activityId,string $view,array $extra=[]): string {
    return '/admin/student-area.php?'.http_build_query(['activity'=>$activityId,'view'=>$view]+$extra);
}
function student_admin_page_links(int $activityId,string $view,int $page,int $pages,array $extra=[]): string {
    if($pages<=1)return '';
    $out='<nav aria-label="Paginação">';
    for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++)$out.='<a '.($i===$page?'aria-current="page" ':'').'href="'.h(student_admin_url($activityId,$view,$extra+['p'=>$i])).'">'.$i.'</a>';
    return $out.'</nav>';
}
function student_admin_datetime(?string $value): string {
    $value=trim((string)$value);if($value==='')return '—';$ts=strtotime($value);return $ts===false?$value:date('d/m/Y H:i',$ts);
}
function student_admin_value(mixed $value): string {$value=trim((string)$value);return $value===''?'—':h($value);}
function student_admin_tabs(int $activityId,string $view): void {
    $items=['overview'=>'Visão geral','cohorts'=>'Turmas','students'=>'Alunos','tests'=>'Testes','lessons'=>'Aulas','pages'=>'Páginas protegidas'];
    echo '<nav class="admin-subtabs" aria-label="Área do aluno">';
    foreach($items as $key=>$label)echo '<a href="'.h(student_admin_url($activityId,$key)).'"'.($view===$key?' aria-current="page"':'').'>'.h($label).'</a>';
    echo '</nav>';
}

if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('student-area',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}
    $action=(string)($_POST['action']??'');
    $returnView=(string)($_POST['return_view']??$view);if(!in_array($returnView,$views,true))$returnView='overview';
    $extra=[];
    try{
        if($action==='create_cohort'){
            $created=course_create_cohort($db,$activityId,(string)($_POST['title']??''),(string)($_POST['slug']??''),!empty($_POST['make_default']));
            $extra=['cohort'=>(int)$created['id']];
        }elseif($action==='update_cohort'){
            $cohortId=(int)($_POST['cohort_id']??0);course_update_cohort_details($db,$activityId,$cohortId,$_POST);$extra=['cohort'=>$cohortId];
        }elseif($action==='set_default_cohort')course_set_default_cohort($db,$activityId,(int)($_POST['cohort_id']??0));
        elseif($action==='set_cohort_status')course_set_cohort_status($db,$activityId,(int)($_POST['cohort_id']??0),(string)($_POST['status']??'active'));
        elseif($action==='add_lesson')course_add_lesson($db,$activityId,(string)($_POST['title']??''),(string)($_POST['lesson_key']??''));
        elseif($action==='set_release')course_set_lesson_release($db,(int)($_POST['cohort_id']??0),(int)($_POST['lesson_id']??0),!empty($_POST['released']));
        elseif($action==='set_page_access')student_page_set_access($db,$activityId,(int)($_POST['page_id']??0),(string)($_POST['access_level']??'public'));
        elseif($action==='save_section_map'){
            $pageId=(int)($_POST['page_id']??0);$page=cms_page_by_id($db,$pageId);if(!$page||(int)$page['activity_id']!==$activityId)throw new RuntimeException('Página inválida.');
            $sections=student_page_sections_from_document(cms_page_doc($page,false));$mapping=is_array($_POST['lesson']??null)?$_POST['lesson']:[];
            foreach($sections as $key=>$label){$lessonId=(int)($mapping[$key]??0);student_page_set_section_lesson($db,$pageId,$key,$lessonId>0?$lessonId:null);} $extra=['page'=>$pageId];
        }elseif($action==='assign_submission_cohort')student_account_assign_submission_cohort($db,(int)($_POST['submission_id']??0),$activityId,(int)($_POST['cohort_id']??0));
        elseif($action==='upload_private_media'){
            $pageId=(int)($_POST['page_id']??0);$file=$_FILES['media_file']??null;if(!is_array($file))throw new RuntimeException('Selecione uma imagem.');$slot=trim((string)($_POST['slot_key']??''));
            if($slot!=='')student_private_media_bind_slot($db,$activityId,$pageId,$slot,(string)($_POST['media_title']??''),$file);else student_private_media_create($db,$activityId,$pageId,(string)($_POST['media_title']??''),$file);$extra=['page'=>$pageId];
        }elseif($action==='import_students'){
            $cohortId=(int)($_POST['cohort_id']??0);$file=$_FILES['spreadsheet']??null;if(!is_array($file))throw new RuntimeException('Selecione uma planilha.');
            $result=student_import_historical_students($db,$activityId,$cohortId,$file);$extra=['import'=>1,'batch'=>(int)$result['batch_id']];
            $_SESSION['admin_notice']='Importação concluída: '.$result['imported'].' nova(s) conta(s), '.$result['existing'].' conta(s) já existente(s), '.$result['errors'].' linha(s) com erro.';
        }elseif($action==='test_message'){
            $testId=(int)($_POST['test_id']??0);student_test_add_admin_message($db,$testId,$activityId,(string)($_POST['message']??''));$extra=['test'=>$testId];
        }elseif($action==='test_status'){
            $testId=(int)($_POST['test_id']??0);student_test_set_review_status($db,$testId,$activityId,(string)($_POST['status']??'submitted'));$extra=['test'=>$testId];
        }elseif($action==='reconcile')student_account_reconcile_confirmed_registrations($db,$activityId);
        else throw new RuntimeException('Ação inválida.');
        if(!isset($_SESSION['admin_notice']))$_SESSION['admin_notice']='Alteração salva.';
    }catch(Throwable $e){$_SESSION['admin_notice']='Não foi possível concluir: '.$e->getMessage();}
    header('Location: '.student_admin_url($activityId,$returnView,$extra),true,303);exit;
}

$cohorts=course_cohorts($db,$activityId);
$lessons=course_lessons($db,$activityId);
$notice=$_SESSION['admin_notice']??null;unset($_SESSION['admin_notice']);
$protectedCountQ=$db->prepare("SELECT COUNT(*) FROM cms_pages WHERE activity_id=? AND status!='archived' AND access_level='enrolled'");$protectedCountQ->execute([$activityId]);$protectedCount=(int)$protectedCountQ->fetchColumn();
$enrollmentCountQ=$db->prepare("SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts c ON c.id=e.cohort_id WHERE c.activity_id=? AND e.status='active'");$enrollmentCountQ->execute([$activityId]);$enrollmentCount=(int)$enrollmentCountQ->fetchColumn();
$releasedCountQ=$db->prepare("SELECT COUNT(*) FROM cohort_lesson_releases r JOIN course_cohorts c ON c.id=r.cohort_id WHERE c.activity_id=? AND r.released_at IS NOT NULL");$releasedCountQ->execute([$activityId]);$releasedCount=(int)$releasedCountQ->fetchColumn();
$testCountQ=$db->prepare("SELECT COUNT(*) FROM student_tests t JOIN course_cohorts c ON c.id=t.cohort_id WHERE c.activity_id=? AND t.status IN ('submitted','needs_revision')");$testCountQ->execute([$activityId]);$testAttentionCount=(int)$testCountQ->fetchColumn();

